#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

CATALOG_PATH = ROOT / 'program_catalog.json'
COOLER_COST_PATH = ROOT / 'cooler_cost.csv'
CONTRACT_PAYMENT_PATH = ROOT / 'contract_payment.csv'
SITE_OVERRIDES_PATH = ROOT / 'site_overrides.csv'
ANALYSIS_PATH = ROOT / 'oncocooler_analysis.json'
SUMMARY_PATH = ROOT / 'oncocooler_summary.md'


def read_csv(path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(value, 2)


def load_in_scope_programs(catalog):
    programs = {}
    label_to_code = {}

    for group in catalog.get('service_groups', []):
        for program in group.get('programs', []):
            if program.get('review_flag') != 'review':
                continue
            code = program['program_code']
            programs[code] = program
            labels = [program.get('program_name', '')] + program.get('known_labels', [])
            for label in labels:
                if label:
                    label_to_code[label] = code

    return programs, label_to_code


def resolve_payments(payment_rows, label_to_code):
    payments = {}
    for row in payment_rows:
        code = label_to_code.get(row['program_label'])
        if code is None:
            continue
        payments[code] = float(row['payment_per_dispatch_per_site_usd'])
    return payments


def resolve_active_sites(site_rows, programs):
    approved_latest = {}
    for row in site_rows:
        if row['approval_state'] != 'approved':
            continue
        code = row['program_code']
        if code not in programs:
            continue
        version = int(row['version_no'])
        if code not in approved_latest or version > approved_latest[code]['version_no']:
            approved_latest[code] = {
                'version_no': version,
                'active_sites': int(row['active_sites']),
            }

    active_sites = {}
    for code, program in programs.items():
        if code in approved_latest:
            active_sites[code] = approved_latest[code]['active_sites']
        else:
            active_sites[code] = int(program['default_active_sites'])
    return active_sites


def compute_model(program, active_sites, payment, cooler_cost, days_per_dispatch, dispatches_per_year):
    annual_drug_cost = (
        float(program['acquisition_cost_per_1000_units_usd'])
        * active_sites
        * float(program['units_per_day'])
        * days_per_dispatch
        * dispatches_per_year
        / 1000
    )
    annual_cooler_cost = cooler_cost * active_sites * dispatches_per_year
    annual_revenue = payment * active_sites * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_cooler_cost
    return annual_drug_cost, annual_cooler_cost, annual_revenue, annual_margin


def main():
    with CATALOG_PATH.open() as f:
        catalog = json.load(f)
    cooler_rows = read_csv(COOLER_COST_PATH)
    payment_rows = read_csv(CONTRACT_PAYMENT_PATH)
    site_rows = read_csv(SITE_OVERRIDES_PATH)

    programs_by_code, label_to_code = load_in_scope_programs(catalog)
    cooler_costs = {row['cooler_type']: float(row['cooler_cost_usd']) for row in cooler_rows}
    payments = resolve_payments(payment_rows, label_to_code)
    active_sites_by_code = resolve_active_sites(site_rows, programs_by_code)

    output_programs = []
    total_10_day_margin = 0.0
    total_20_day_margin = 0.0

    for code in sorted(programs_by_code):
        program = programs_by_code[code]
        active_sites = active_sites_by_code[code]
        payment = payments.get(code)
        if payment is None:
            continue
        cooler_type = program['cooler_type']
        cooler_cost = cooler_costs[cooler_type]

        drug_10, cooler_10, revenue_10, margin_10 = compute_model(
            program, active_sites, payment, cooler_cost, days_per_dispatch=10, dispatches_per_year=36
        )
        drug_20, cooler_20, revenue_20, margin_20 = compute_model(
            program, active_sites, payment, cooler_cost, days_per_dispatch=20, dispatches_per_year=18
        )
        margin_difference = margin_20 - margin_10

        total_10_day_margin += margin_10
        total_20_day_margin += margin_20

        output_programs.append({
            'program_code': code,
            'program_name': program['program_name'],
            'active_sites': active_sites,
            'acquisition_cost_per_1000_units_usd': money(float(program['acquisition_cost_per_1000_units_usd'])),
            'units_per_day': float(program['units_per_day']),
            'cooler_type': cooler_type,
            'cooler_cost_usd': money(cooler_cost),
            'payment_per_dispatch_per_site_usd': money(payment),
            'annual_drug_cost_10_day': money(drug_10),
            'annual_cooler_cost_10_day': money(cooler_10),
            'annual_revenue_10_day': money(revenue_10),
            'annual_margin_10_day': money(margin_10),
            'annual_drug_cost_20_day': money(drug_20),
            'annual_cooler_cost_20_day': money(cooler_20),
            'annual_revenue_20_day': money(revenue_20),
            'annual_margin_20_day': money(margin_20),
            'annual_margin_difference_20_minus_10': money(margin_difference),
        })

    total_difference = total_20_day_margin - total_10_day_margin
    absolute_total_difference = abs(total_difference)
    decision = 'move_to_20_day' if absolute_total_difference < 10000 else 'keep_10_day'

    result = {
        'programs': output_programs,
        'totals': {
            'total_10_day_margin': money(total_10_day_margin),
            'total_20_day_margin': money(total_20_day_margin),
            'total_difference': money(total_difference),
            'absolute_total_difference': money(absolute_total_difference),
        },
        'recommendation': {
            'decision': decision,
        },
    }

    with ANALYSIS_PATH.open('w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary_lines = [
        f"Total 10-day margin: ${result['totals']['total_10_day_margin']:,.2f} USD",
        f"Total 20-day margin: ${result['totals']['total_20_day_margin']:,.2f} USD",
        f"Absolute difference: ${result['totals']['absolute_total_difference']:,.2f} USD",
        f"Decision: {decision}",
    ]
    SUMMARY_PATH.write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
